<script setup lang="ts">
import JobCard from '~/components/jobs/JobCard.vue'
import Select from 'primevue/select'
import InputText from 'primevue/inputtext'

useSeoMeta({ title: 'Job Board | Alumni Portal', description: 'Job opportunities posted by and for alumni.' })

const { fetchJobs, fetchCategories } = useJobs()

const search = ref('')
const selectedCategory = ref<number | null>(null)
const selectedType = ref<string | null>(null)
const remote = ref<boolean | null>(null)

const categories = ref<{ label: string, value: number | null }[]>([])
const catList = await fetchCategories()
categories.value = [
  { label: 'All Categories', value: null },
  ...catList.map(c => ({ label: c.name, value: c.id })),
]

const jobTypes = [
  { label: 'All Types', value: null },
  { label: 'Full Time', value: 'full_time' },
  { label: 'Part Time', value: 'part_time' },
  { label: 'Contract', value: 'contract' },
  { label: 'Internship', value: 'internship' },
  { label: 'Freelance', value: 'freelance' },
]

const { data: jobs, refresh, pending } = await useAsyncData('jobs', () =>
  fetchJobs({
    search: search.value || undefined,
    categoryId: selectedCategory.value || undefined,
    jobType: selectedType.value || undefined,
    isRemote: remote.value ?? undefined,
  }),
)

const debounceTimeout = ref<ReturnType<typeof setTimeout>>()
function onSearch() {
  clearTimeout(debounceTimeout.value)
  debounceTimeout.value = setTimeout(refresh, 300)
}

watch([selectedCategory, selectedType, remote], refresh)
</script>

<template>
  <div>
    <div class="bg-white border-b border-slate-200 py-8 px-4">
      <div class="max-w-6xl mx-auto">
        <h1 class="text-2xl font-bold text-slate-900">Job Board</h1>
        <p class="text-slate-500 text-sm mt-1">Opportunities posted by alumni and partner organizations</p>

        <div class="mt-4 flex flex-wrap gap-3">
          <InputText
            v-model="search"
            placeholder="Search jobs..."
            class="flex-1 min-w-48"
            @input="onSearch"
          />
          <Select
            v-model="selectedCategory"
            :options="categories"
            option-label="label"
            option-value="value"
            placeholder="Category"
            class="w-48"
          />
          <Select
            v-model="selectedType"
            :options="jobTypes"
            option-label="label"
            option-value="value"
            placeholder="Job Type"
            class="w-40"
          />
          <button
            class="flex items-center gap-1.5 px-3 py-2 text-sm rounded-lg border transition-colors"
            :class="remote ? 'bg-green-50 border-green-300 text-green-700' : 'border-slate-200 text-slate-600 hover:bg-slate-50'"
            @click="remote = remote ? null : true"
          >
            <i class="pi pi-globe text-xs" />
            Remote
          </button>
        </div>
      </div>
    </div>

    <div class="max-w-6xl mx-auto px-4 py-8">
      <div v-if="pending" class="space-y-3">
        <div v-for="i in 5" :key="i" class="bg-white border border-slate-200 rounded-xl h-24 animate-pulse" />
      </div>
      <div v-else-if="jobs && jobs.length > 0" class="space-y-3">
        <JobCard v-for="job in jobs" :key="job.id" :job="job" />
      </div>
      <div v-else class="text-center py-16">
        <i class="pi pi-briefcase text-4xl text-slate-300 mb-3 block" />
        <p class="text-slate-500">No jobs found</p>
      </div>
    </div>
  </div>
</template>
